using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Http;
using Microsoft.Extensions.Caching.Memory;
using Microsoft.Extensions.DependencyInjection;
using System;
using System.Threading.Tasks;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddMemoryCache();
builder.Services.AddHttpClient();
var app = builder.Build();

// Middleware to cache API responses based on request path and query parameters
app.Use(async (context, next) =>
{
    var cache = context.RequestServices.GetRequiredService<IMemoryCache>();

    // Build cache key from Host header + path + query string
    var host = context.Request.Headers["Host"].ToString();
    var xForwardedHost = context.Request.Headers["X-Forwarded-Host"].ToString();
    var effectiveHost = !string.IsNullOrEmpty(xForwardedHost) ? xForwardedHost : host;

    var cacheKey = $"{effectiveHost}:{context.Request.Path}{context.Request.QueryString}";

    if (cache.TryGetValue(cacheKey, out CachedResponse? cached) && cached != null)
    {
        context.Response.StatusCode = cached.StatusCode;
        context.Response.ContentType = cached.ContentType;
        context.Response.Headers["X-Cache"] = "HIT";
        context.Response.Headers["X-Cache-Key"] = cacheKey;
        await context.Response.WriteAsync(cached.Body);
        return;
    }

    var originalBodyStream = context.Response.Body;
    using var responseBody = new System.IO.MemoryStream();
    context.Response.Body = responseBody;

    await next();

    responseBody.Seek(0, System.IO.SeekOrigin.Begin);
    var body = await new System.IO.StreamReader(responseBody).ReadToEndAsync();

    // Cache successful GET responses for 5 minutes
    if (context.Request.Method == "GET" && context.Response.StatusCode == 200)
    {
        var entry = new CachedResponse
        {
            StatusCode = context.Response.StatusCode,
            ContentType = context.Response.ContentType ?? "application/json",
            Body = body
        };
        cache.Set(cacheKey, entry, TimeSpan.FromMinutes(5));
        context.Response.Headers["X-Cache"] = "MISS";
    }

    responseBody.Seek(0, System.IO.SeekOrigin.Begin);
    await responseBody.CopyToAsync(originalBodyStream);
});

app.MapGet("/api/config", () =>
{
    return Results.Json(new
    {
        apiEndpoint = "https://internal-api.corp.example.com/v2",
        cdnBase = "https://assets.corp.example.com",
        authProvider = "https://auth.corp.example.com/oauth2",
        version = "3.1.4"
    });
});

app.MapGet("/api/users/{id}", (int id) =>
{
    // Simulated user lookup
    return Results.Json(new { id, name = $"User_{id}", email = $"user{id}@corp.example.com" });
});

app.MapGet("/api/health", () => Results.Ok(new { status = "healthy", timestamp = DateTime.UtcNow }));

app.MapPost("/api/cache/purge", (HttpContext ctx) =>
{
    // No authentication on purge endpoint - relies on network isolation
    var cache = ctx.RequestServices.GetRequiredService<IMemoryCache>();
    if (cache is MemoryCache mc)
    {
        mc.Compact(1.0);
    }
    return Results.Ok(new { purged = true });
});

app.Run("http://0.0.0.0:8080");

public class CachedResponse
{
    public int StatusCode { get; set; }
    public string ContentType { get; set; } = "";
    public string Body { get; set; } = "";
}
